DELIMITER ;;
CREATE DEFINER=`obed.vargas`@`%` PROCEDURE `sp_completar_productos_practica`(IN p_cantidad INT)
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE v_prefix VARCHAR(10);
    DECLARE v_tipo VARCHAR(50);
    DECLARE v_marca VARCHAR(50);
    DECLARE v_sku VARCHAR(50);
    DECLARE v_nombre VARCHAR(250);
    DECLARE v_desc TEXT;
    DECLARE v_precio DECIMAL(10,2);
    DECLARE v_stock INT;
    
    START TRANSACTION;
    
    WHILE i <= p_cantidad DO
        SET v_prefix = ELT(1 + FLOOR(RAND() * 8), 'ELE', 'AUD', 'GAM', 'ACC', 'RED', 'ALM', 'MOV', 'OFI');
        SET v_tipo = CASE v_prefix
            WHEN 'ELE' THEN ELT(1 + FLOOR(RAND() * 3), 'Laptop', 'Monitor LED', 'Tablet')
            WHEN 'AUD' THEN ELT(1 + FLOOR(RAND() * 3), 'Audífonos Bluetooth', 'Barra de sonido', 'Bocina portátil')
            WHEN 'GAM' THEN ELT(1 + FLOOR(RAND() * 3), 'Mouse Gamer', 'Teclado Mecánico', 'Control inalámbrico')
            WHEN 'ACC' THEN ELT(1 + FLOOR(RAND() * 3), 'Hub USB-C', 'Cargador Rápido GaN', 'Webcam 1080p')
            WHEN 'RED' THEN ELT(1 + FLOOR(RAND() * 3), 'Router Wi-Fi 6', 'Switch Gigabit', 'Punto de Acceso')
            WHEN 'ALM' THEN ELT(1 + FLOOR(RAND() * 3), 'Disco Duro Externo', 'Unidad SSD NVMe', 'Memoria USB 3.2')
            WHEN 'MOV' THEN ELT(1 + FLOOR(RAND() * 3), 'Smartphone 5G', 'Smartwatch Active', 'Batería Portátil')
            WHEN 'OFI' THEN ELT(1 + FLOOR(RAND() * 3), 'Impresora Multifuncional', 'Trituradora de papel', 'Lámpara de escritorio LED')
        END;
        
        SET v_marca = ELT(1 + FLOOR(RAND() * 8), 'Samsung', 'Sony', 'Logitech', 'Kingston', 'Xiaomi', 'Dell', 'Asus', 'HP');
        SET v_sku = CONCAT(v_prefix, '-', UPPER(SUBSTRING(v_marca, 1, 3)), '-', LPAD(5007 + i, 5, '0'), '-', UPPER(SUBSTRING(MD5(RAND()), 1, 4)));
        SET v_nombre = CONCAT(v_marca, ' ', v_tipo, ' Advance ', LPAD(i, 4, '0'));
        SET v_desc = CONCAT(v_tipo, ' ', v_marca, ', versión profesional con alta durabilidad y soporte para trabajo o entretenimiento.');
        SET v_precio = ROUND(180 + (RAND() * 18500), 2);
        SET v_stock = FLOOR(RAND() * 90);
        
        INSERT INTO `tb_products` (`SKU`, `name`, `description`, `current_price`, `current_stock`, `status`, `creation_date`)
        VALUES (v_sku, v_nombre, v_desc, v_precio, v_stock, b'1', NOW());
        
        SET i = i + 1;
    END WHILE;
    
    COMMIT;
END ;;
DELIMITER ;
